(() => {
  const clean = (s) => (s || '').replace(/\u00a0/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  return [...document.querySelectorAll('input,textarea,[contenteditable=true]')].filter(vis)
    .map((e,i) => i + ':' + (e.placeholder||'').slice(0,18) + '=' + clean(e.value||e.innerText).slice(0,40)).slice(0,12);
})()

